 trace=[a for a in r['route_trace']if a['unit']in ['lance','hervi']and a['to'][0]>=21 and a['to'][1]<=8]
 if label=='final-flank':assert all(r['flank_arrived'].get(u)for u in ['lance','hervi'])and trace
 plays.append({'label':label,'title':title,'turns':int(b['final_turn']),'inputs':int(b['key_inputs']),'residents_alive':3,'evacuated':v['flags']['quest']['evacuated'],'formal_alive':8,'formal_total':8,'map_sha256':current_hash,'return_view':b['return_view'],'source':str(p.relative_to(O)),'northern_crossing_trace':trace})
