script='''const descriptions={plain:'默认纯场景；标注只用于本页说明，不加入游戏画面。',routes:'赭色：主桥与撤离主线。蓝色：东北林桥绕行线。两线在医舍附近会合。',actors:'蓝：本次8名实际出阵者的部署。红：13名初始守军。金：居民。绿：两处交互。出：南侧出口。'};function selectLayer(mode){document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layer===mode)));document.querySelectorAll('.overlay').forEach(g=>g.classList.toggle('active',g.id===mode));document.getElementById('legend').textContent=descriptions[mode];}document.querySelectorAll('[data-layer]').forEach(b=>b.addEventListener('click',()=>selectLayer(b.dataset.layer)));'''
